css:
.salto-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #0f1923 0%, #1a2a3a 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    color: #e0e6ed;
}

.salto-sim-container h1,
.salto-sim-container h3,
.salto-sim-container h4 {
    color: #ffffff;
}

.salto-sim-header {
    background: linear-gradient(135deg, #0066cc 0%, #004999 100%);
    color: white;
    padding: 30px;
    border-radius: 16px;
    margin-bottom: 24px;
    box-shadow: 0 8px 24px rgba(0,102,204,0.3);
    text-align: center;
}

.salto-sim-header p {
    margin: 8px 0 0 0;
    opacity: 0.85;
    font-size: 1.05rem;
}

.salto-sim-period-counter {
    text-align: center;
    font-size: 1.15rem;
    margin-bottom: 24px;
    color: #8899aa;
}

.salto-sim-period-counter #roundTitle {
    display: inline-block;
    color: #4dabf7;
    font-weight: 600;
}

.salto-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}

.salto-sim-status-card {
    background: #1e2d3d;
    border: 1px solid #2a3f55;
    border-radius: 12px;
    padding: 20px 16px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.2);
    transition: transform 0.3s ease;
    text-align: center;
}

.salto-sim-status-card:hover {
    transform: translateY(-3px);
}

.salto-sim-label {
    color: #7a8fa2;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.salto-sim-value {
    font-size: 1.8rem;
    font-weight: 700;
    color: #4dabf7;
}

.salto-sim-event-alert {
    background: linear-gradient(135deg, #7c4a00 0%, #a36200 100%);
    border: 1px solid #d4890a;
    border-radius: 10px;
    padding: 16px 20px;
    margin-bottom: 20px;
    color: #fff;
    font-size: 0.95rem;
}

.salto-sim-briefing {
    background: #162230;
    border: 1px solid #2a3f55;
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 24px;
    line-height: 1.65;
    font-size: 0.95rem;
}

.salto-sim-decisions {
    background: #1a2d40;
    border: 1px solid #2a3f55;
    border-radius: 12px;
    padding: 24px;
    margin-bottom: 24px;
}

.salto-sim-decisions h3 {
    margin-top: 24px;
    margin-bottom: 12px;
    padding-bottom: 8px;
    border-bottom: 1px solid #2a3f55;
}

.salto-sim-decisions h3:first-child {
    margin-top: 0;
}

.salto-sim-slider-group {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
}

.salto-sim-slider-group label {
    min-width: 260px;
    color: #c0cdd8;
    font-size: 0.9rem;
}

.salto-sim-range {
    flex: 1;
    accent-color: #4dabf7;
}

.salto-sim-range-val {
    min-width: 32px;
    text-align: center;
    font-weight: 700;
    color: #4dabf7;
    font-size: 1.2rem;
}

.salto-sim-maturity-result {
    background: #0d1b2a;
    border: 1px solid #4dabf7;
    border-radius: 8px;
    padding: 16px;
    margin: 16px 0;
    color: #4dabf7;
    font-weight: 600;
}

.salto-sim-initiative-grid {
    margin-bottom: 20px;
}

.salto-sim-initiative-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 8px 12px;
    border-bottom: 1px solid #1e2d3d;
}

.salto-sim-initiative-row:nth-child(odd) {
    background: rgba(255,255,255,0.02);
}

.salto-sim-initiative-name {
    flex: 1;
    color: #c0cdd8;
    font-size: 0.9rem;
}

.salto-sim-ini-select {
    width: 200px;
    background: #0d1b2a;
    color: #e0e6ed;
    border: 1px solid #2a3f55;
}

.salto-sim-radio-group {
    margin-bottom: 16px;
}

.salto-sim-radio-option {
    display: block;
    padding: 12px 16px;
    margin-bottom: 8px;
    background: #0d1b2a;
    border: 1px solid #2a3f55;
    border-radius: 8px;
    cursor: pointer;
    transition: border-color 0.2s, background 0.2s;
    color: #c0cdd8;
    font-size: 0.9rem;
    line-height: 1.5;
}

.salto-sim-radio-option:hover {
    border-color: #4dabf7;
    background: #162230;
}

.salto-sim-radio-option input[type="radio"] {
    margin-right: 10px;
    accent-color: #4dabf7;
}

.salto-sim-capability-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 20px;
    margin-bottom: 24px;
}

.salto-sim-capability-card {
    background: #0d1b2a;
    border: 1px solid #2a3f55;
    border-radius: 10px;
    padding: 20px;
}

.salto-sim-capability-card h4 {
    margin: 0 0 8px 0;
    color: #4dabf7;
}

.salto-sim-cap-options {
    margin: 12px 0;
}

.salto-sim-cap-detail {
    padding: 4px 0;
    font-size: 0.85rem;
    color: #8899aa;
}

.salto-sim-cap-detail strong {
    color: #c0cdd8;
}

.salto-sim-cap-select {
    background: #1a2d40;
    color: #e0e6ed;
    border: 1px solid #2a3f55;
    margin-top: 8px;
}

.salto-sim-resistance-card {
    background: #0d1b2a;
    border: 1px solid #2a3f55;
    border-radius: 10px;
    padding: 20px;
    margin-bottom: 20px;
}

.salto-sim-resistance-card h4 {
    color: #ff8c42;
    margin: 0 0 10px 0;
}

.salto-sim-resistance-card > p {
    font-style: italic;
    color: #8899aa;
    border-left: 3px solid #ff8c42;
    padding-left: 12px;
    margin-bottom: 16px;
}

.salto-sim-controls {
    text-align: center;
    margin-bottom: 30px;
}

.salto-sim-controls .btn-primary {
    background: linear-gradient(135deg, #0066cc 0%, #004999 100%);
    border: none;
    padding: 12px 48px;
    font-size: 1.1rem;
    border-radius: 8px;
    margin-right: 12px;
}

.salto-sim-controls .btn-primary:hover {
    background: linear-gradient(135deg, #0077ee 0%, #005abb 100%);
}

.salto-sim-controls .btn-outline-secondary {
    color: #7a8fa2;
    border-color: #2a3f55;
}

.salto-sim-history {
    margin-bottom: 30px;
}

.salto-sim-container .table {
    color: #c0cdd8;
    background: #1e2d3d;
}

.salto-sim-container .table th {
    background: #0d1b2a;
    color: #4dabf7;
    border-color: #2a3f55;
}

.salto-sim-container .table td {
    border-color: #2a3f55;
}

.salto-sim-chart {
    background: #1e2d3d;
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 20px;
    min-height: 280px;
}

@media (max-width: 768px) {
    .salto-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .salto-sim-slider-group {
        flex-wrap: wrap;
    }
    .salto-sim-slider-group label {
        min-width: 100%;
    }
    .salto-sim-initiative-row {
        flex-direction: column;
        align-items: flex-start;
    }
    .salto-sim-ini-select {
        width: 100%;
    }
}

