        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.roundScore || 0 : 0; });
            var total = scores.reduce(function(s, v) { return s + v; }, 0);
            var avg = total / scores.length;

            var lastEntry = history[history.length - 1];
            var compositeScore = lastEntry.results ? lastEntry.results.compositeScore || 0 : 0;

            var performance = 'Beginner';
            if (compositeScore >= 80) performance = 'Excellent — Digital Transformation Leader';
            else if (compositeScore >= 60) performance = 'Good — Solid Transformation Foundation';
            else if (compositeScore >= 40) performance = 'Developing — Key Gaps Remain';

            var insights = [];
            if (compositeScore >= 80) {
                insights.push('Strong strategic coherence across all transformation dimensions.');
                insights.push('Stakeholder management approach builds organizational buy-in effectively.');
            } else if (compositeScore >= 60) {
                insights.push('Good foundation — review capability architecture decisions for optimization.');
                insights.push('Consider whether stakeholder alignment was addressed before the business model transition.');
            } else {
                insights.push('Digital transformation requires addressing organizational resistance before changing the business model.');
                insights.push('Review the Build/Buy/Partner framework — strategic differentiation should drive capability decisions.');
            }

            return {
                compositeScore: compositeScore,
                averageRoundScore: Math.round(avg),
                performance: performance,
                insights: insights
            };
        }

